INSERT INTO folder (
    folder_code, workspace_id, parent_id, name, is_root, status, deleted_at, created_at, updated_at
) VALUES (
    #{folderCode}, #{workspaceId}, #{parentId}, #{name}, #{root}, #{status}, #{deletedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
WITH RECURSIVE ancestor_chain AS ( SELECT id, folder_code, workspace_id, parent_id, name, is_root, status, deleted_at, created_at, updated_at, 0 AS depth FROM folder WHERE id = #{folderId}
UNION ALL
SELECT f.id, f.folder_code, f.workspace_id, f.parent_id, f.name, f.is_root, f.status, f.deleted_at, f.created_at, f.updated_at, ancestor_chain.depth + 1 FROM folder f INNER JOIN ancestor_chain ON f.id = ancestor_chain.parent_id WHERE ancestor_chain.depth < 255 ) SELECT id, folder_code, workspace_id, parent_id, name, is_root, status, deleted_at, created_at, updated_at FROM ancestor_chain ORDER BY depth ASC

SELECT 
FROM folder
WHERE workspace_id = #{workspaceId}
  AND parent_id = #{parentId}
  AND name = #{name}
  AND status = 0
LIMIT 1

SELECT 
FROM folder
WHERE workspace_id = #{workspaceId}
  AND parent_id = #{parentId}
  AND status = 0
ORDER BY name, id
